static void check(bool p,const char*s){if(!p){std::cerr<<"FAIL: "<<s<<'\n';std::exit(1);}}
static bool near(double a,double b){return std::abs(a-b)<1e-6;}
static bool sameKey(const AnimKey&a,const AnimKey&b){return a.time==b.time&&a.value==b.value&&a.interpolation==b.interpolation&&a.outX==b.outX&&a.outY==b.outY&&a.inX==b.inX&&a.inY==b.inY&&a.outAbsolute==b.outAbsolute&&a.inAbsolute==b.inAbsolute&&a.legacyFrom==b.legacyFrom&&a.legacyTo==b.legacyTo;}
static bool sameGeometry(const Geometry&a,const Geometry&b){return a.shape==b.shape&&a.mode==b.mode&&a.reveal==b.reveal&&a.depthOrder==b.depthOrder&&near(a.width,b.width)&&near(a.height,b.height)&&near(a.thickness,b.thickness)&&near(a.softness,b.softness)&&near(a.spacing,b.spacing)&&near(a.sides,b.sides)&&near(a.shear,b.shear)&&near(a.opacity,b.opacity)&&near(a.detail,b.detail)&&near(a.plane.position.x,b.plane.position.x)&&near(a.plane.position.y,b.plane.position.y)&&near(a.plane.position.z,b.plane.position.z)&&near(a.plane.rotation.x,b.plane.rotation.x)&&near(a.plane.rotation.y,b.plane.rotation.y)&&near(a.plane.rotation.z,b.plane.rotation.z)&&near(a.plane.scaleX,b.plane.scaleX)&&near(a.plane.scaleY,b.plane.scaleY);}
